<?php
$config = require __DIR__ . '/config.php';
date_default_timezone_set($config['timezone']);
if (session_status() !== PHP_SESSION_ACTIVE && PHP_SAPI !== 'cli') {
 session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off']);
 session_start();
}
function db(): PDO { static $pdo; global $config; if (!$pdo) { $pdo = new PDO('mysql:host='.$config['db_host'].';port='.$config['db_port'].';dbname='.$config['db_name'].';charset=utf8mb4', $config['db_user'], $config['db_pass'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]); $pdo->exec("SET time_zone = '+08:00'"); } return $pdo; }
function q(string $sql, array $params=[]): PDOStatement { $s=db()->prepare($sql); $s->execute($params); return $s; }
function h($s): string { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function url(string $page='dashboard'): string { return 'index.php?page='.urlencode($page); }
function go(string $page='dashboard'): void { header('Location: '.url($page)); exit; }
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function token(): string { return '<input type="hidden" name="csrf" value="'.h(csrf()).'">'; }
function check_csrf(): void { if (!isset($_POST['csrf']) || !hash_equals(csrf(),(string)$_POST['csrf'])) { http_response_code(403); exit('Invalid form token. Reload the page and try again.'); } }
function user(): ?array { if(empty($_SESSION['user_id'])) return null; return q('SELECT id,name,email,role FROM users WHERE id=?',[(int)$_SESSION['user_id']])->fetch() ?: null; }
function require_user(): array { $u=user(); if(!$u) go('login'); return $u; }
function require_role(array $u,string $role): void { if($u['role']!==$role){http_response_code(403);exit('Access denied.');} }
function flash(string $m,string $type='success'): void { $_SESSION['flash']=['text'=>$m,'type'=>$type]; }
function log_event(?int $id,string $event): void { q('INSERT INTO activity_log(user_id,event) VALUES (?,?)',[$id,$event]); }
function valid_date(string $value): bool { $d=DateTime::createFromFormat('!Y-m-d',$value); return $d && $d->format('Y-m-d')===$value; }
function insights(int $patient): array {
 $s=q("SELECT COUNT(*) total, SUM(status='taken') taken, SUM(status='missed') missed, SUM(status='skipped') skipped FROM doses WHERE patient_id=? AND status IN ('taken','missed','skipped') AND scheduled_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)",[$patient])->fetch();
 $total=(int)$s['total']; $taken=(int)$s['taken']; $missed=(int)$s['missed']; $skipped=(int)$s['skipped']; $rate=$total?round(100*$taken/$total):null;
 $pattern=q("SELECT HOUR(scheduled_at) hour, COUNT(*) n FROM doses WHERE patient_id=? AND status IN ('missed','skipped') AND scheduled_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY HOUR(scheduled_at) ORDER BY n DESC,hour LIMIT 1",[$patient])->fetch();
 // Logistic regression coefficients generated by ml/train.py from synthetic data only.
 $model=json_decode(file_get_contents(__DIR__.'/ml/model.json'),true);
 $risk=null; if($total && is_array($model)){ $missRate=($missed+$skipped)/$total; $z=$model['intercept']+$model['miss_rate']*$missRate+$model['few_records']*($total<7?1:0); $risk=round(100/(1+exp(-$z))); }
 return ['total'=>$total,'taken'=>$taken,'missed'=>$missed,'skipped'=>$skipped,'rate'=>$rate,'pattern'=>$pattern,'risk'=>$risk];
}
// Idempotent scheduled job. Run once a minute from cron / Windows Task Scheduler.
function process_reminders(): void {
 global $config;
 // Materialize current day's scheduled doses; backfill a maximum of 30 days after downtime,
 // beginning at each medication's start date, and never after deactivation.
 $meds=q('SELECT * FROM medications WHERE active=1 AND start_date<=CURDATE() AND (end_date IS NULL OR end_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY))')->fetchAll();
 $today=new DateTimeImmutable('today');
 foreach($meds as $m){
  $start=new DateTimeImmutable($m['start_date']); $floor=$today->modify('-30 days'); if($start<$floor)$start=$floor;
  $end=empty($m['end_date'])?$today:new DateTimeImmutable($m['end_date']); if($end>$today)$end=$today;
  for($d=$start;$d<=$end;$d=$d->modify('+1 day')) q('INSERT IGNORE INTO doses(medication_id,patient_id,scheduled_at) VALUES (?,?,?)',[$m['id'],$m['patient_id'],$d->format('Y-m-d').' '.$m['scheduled_time']]);
 }
 $minutes=max(1,(int)$config['missed_after_minutes']);
 // Per-dose conditional update ensures duplicate concurrent workers do not send duplicates.
 $expired=q("SELECT d.id,d.patient_id,d.scheduled_at,m.name,u.name patient_name FROM doses d JOIN medications m ON m.id=d.medication_id JOIN users u ON u.id=d.patient_id WHERE d.status='pending' AND d.scheduled_at <= DATE_SUB(NOW(), INTERVAL $minutes MINUTE) AND (d.remind_at IS NULL OR d.remind_at <= DATE_SUB(NOW(), INTERVAL 5 MINUTE))")->fetchAll();
 foreach($expired as $d){
  db()->beginTransaction();
  try { $updated=q("UPDATE doses SET status='missed',responded_at=NOW() WHERE id=? AND status='pending' AND scheduled_at <= DATE_SUB(NOW(), INTERVAL $minutes MINUTE) AND (remind_at IS NULL OR remind_at <= DATE_SUB(NOW(), INTERVAL 5 MINUTE))",[$d['id']])->rowCount();
   if($updated){ $links=q('SELECT caregiver_id FROM caregiver_links WHERE patient_id=?',[$d['patient_id']])->fetchAll(); foreach($links as $link) q('INSERT IGNORE INTO notifications(recipient_id,dose_id,message) VALUES (?,?,?)',[$link['caregiver_id'],$d['id'],$d['patient_name'].' missed the scheduled '.$d['name'].' dose at '.date('M j, g:i A',strtotime($d['scheduled_at'])).'.']); }
   db()->commit();
  } catch(Throwable $e){db()->rollBack();throw $e;}
 }
}
